WITH enriched AS (SELECT *, DENSE_RANK() OVER (PARTITION BY region ORDER BY sqft DESC) AS sqft_dense_rank, NTILE(5) OVER (PARTITION BY city, region ORDER BY sqft DESC, id) AS sqft_bucket FROM stores) SELECT region, DATE_TRUNC('MONTH', opened_date) AS activity_month, COUNT(*) AS num_rows, APPROX_PERCENTILE(sqft_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS sqft_dense_rank_quartiles, COUNT_IF(region = 'East') AS east_events, SIZE(COLLECT_SET(region)) AS num_regions, SIZE(COLLECT_SET(city)) AS num_cities FROM enriched GROUP BY ROLLUP (region, DATE_TRUNC('MONTH', opened_date));
